#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Print the newest mission summary generated by task_evidence_recorder.py."""

from __future__ import print_function

import glob
import json
import os
import sys


def main():
    log_root = os.path.expandvars(os.path.expanduser(sys.argv[1] if len(sys.argv) > 1 else '~/.ros/myrobot_description_logs'))
    mission_dirs = sorted([p for p in glob.glob(os.path.join(log_root, 'mission_*')) if os.path.isdir(p)])
    if not mission_dirs:
        print('No mission logs found under: %s' % log_root)
        return 1

    latest = mission_dirs[-1]
    summary_path = os.path.join(latest, 'mission_summary.md')
    print('Latest mission log: %s' % latest)
    print('')
    if os.path.exists(summary_path):
        with open(summary_path, 'r') as f:
            print(f.read())
    else:
        print('mission_summary.md not found. The mission may still be running or was interrupted early.')

    recognition_path = os.path.join(latest, 'recognition_results.jsonl')
    if os.path.exists(recognition_path):
        print('Recognition results:')
        with open(recognition_path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    data = json.loads(line)
                    print('- {zone}: enemy={enemy}, friendly={friendly}, hostage={hostage}'.format(**data))
                except Exception:
                    print('- %s' % line)
    return 0


if __name__ == '__main__':
    sys.exit(main())
